def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import shlex
    import os

    def run_command(command: str) -> subprocess.CompletedProcess:
        return subprocess.run(shlex.split(command), capture_output=True)

    results = []
    commands = []

    for arg in varargs:
        full_cmd = f"{' '.join(cmd)} {arg}"
        if len(full_cmd) > _max_length:
            raise ValueError("Command line length exceeds the maximum limit for this platform.")
        commands.append(full_cmd)

    if target_concurrency > 1:
        import concurrent.futures

        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            future_to_cmd = {executor.submit(run_command, cmd): cmd for cmd in commands}
            for future in concurrent.futures.as_completed(future_to_cmd):
                cmd = future_to_cmd[future]
                try:
                    results.append(future.result())
                except Exception as e:
                    print(f"Command {cmd} generated an exception: {e}")
                    results.append(subprocess.CompletedProcess(shlex.split(cmd), returncode=1, stdout=b'', stderr=str(e).encode()))
    else:
        for cmd in commands:
            result = run_command(cmd)
            results.append(result)

    overall_returncode = 0
    overall_output = b''.join(result.stdout for result in results)
    for result in results:
        if result.returncode != 0:
            overall_returncode = result.returncode

    return overall_returncode, overall_output

