def _legacy_mergeOrderings(orderings):
    result = []
    for ordering in orderings:
        # Find the index of the first element of the current ordering in the result
        index = None
        for item in ordering:
            if item in result:
                index = result.index(item)
                break
        if index is None:
            # If no element is found in the result, append the whole ordering
            result.extend(ordering)
        else:
            # Insert the elements before the found index
            result[index:index] = [item for item in reversed(ordering) if item not in result[index:]]
    return result

