def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		if isinstance(params, Mapping):
			out_params = {f":{key}": value for key, value in params.items()}
			for key in out_params:
				sql = sql.replace(f"%({key[1:-1]})s", key)
		else:
			out_params = [value for value in params]
			for i, _ in enumerate(out_params):
				sql = sql.replace(f"%s", f":{i}", 1)
		return sql, out_params

def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		# Assuming in-style is '?' and out-style is ':paramN' for ordinal and ':key' for named
		if isinstance(params, dict):
			# Named parameters
			out_params = {f':{key}': value for key, value in params.items()}
			for key in out_params:
				sql = sql.replace(f':{key[1:]}', key)
		else:
			# Ordinal parameters
			out_params = [f':param{i+1}' for i in range(len(params))]
			for i, param in enumerate(out_params):
				sql = sql.replace('?', param)
		return sql, list(out_params.values()) if isinstance(params, Sequence) else out_params

