				for key, value in params.items():
					placeholder = f":{key}" if isinstance(key, str) else f":{i+1}"
					out_style_sql = out_style_sql.replace(f"%({key})s", placeholder)
					new_params[placeholder] = value
				out_style_params.append(new_params)
			else:
				# Ordinal parameters
				new_params = []
				for j, value in enumerate(params):
					placeholder = f":{j+1}"
					out_style_sql = out_style_sql.replace("%s", placeholder, 1)
					new_params.append(value)
				out_style_params.append(new_params)

		return out_style_sql, out_style_params

