def _explore_folder(folder):
    from os import path, listdir
    import xml.etree.ElementTree as ET

    data = {}
    for file in listdir(folder):
        if file.endswith('.xml'):
            base_name = path.splitext(file)[0]
            file_path = path.join(folder, file)
            tree = ET.parse(file_path)
            root = tree.getroot()
            if base_name not in data:
                data[base_name] = []
            data[base_name].append({child.tag: child.text for child in root})
    return data

def _explore_folder(folder):
    import os
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    packages_data = defaultdict(list)

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                base_name = os.path.splitext(file)[0]
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    packages_data[base_name].append(ET.tostring(root_element, encoding='unicode'))
                except ET.ParseError as e:
                    print(f"Error parsing {file_path}: {e}")

    return dict(packages_data)

