def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if right == ( '|', left, object() ):
                    result.append(left)
                elif right == ( '&', ( '~', left ), object() ):
                    result.append(( '&', left, right[2] ))
            elif op == '|':
                if right == ( '&', left, object() ):
                    result.append(left)
                elif right == ( '|', ( '~', left ), object() ):
                    result.append(( '|', left, right[2] ))
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections import namedtuple
    Expr = namedtuple('Expr', 'op, left, right')

    def apply_absorption(expr):
        if expr.op == '&' and expr.right.op == '|':
            if expr.left == expr.right.left:
                return expr.left
            if expr.left == expr.right.right:
                return expr.left
        if expr.op == '|' and expr.right.op == '&':
            if expr.left == expr.right.left:
                return expr.left
            if expr.left == expr.right.right:
                return expr.left
        if expr.op == '&' and expr.right.op == '|':
            if expr.left == Expr('~', expr.right.left, None):
                return Expr('&', expr.left, expr.right.right)
            if expr.left == Expr('~', expr.right.right, None):
                return Expr('&', expr.left, expr.right.left)
        if expr.op == '|' and expr.right.op == '&':
            if expr.left == Expr('~', expr.right.left, None):
                return Expr('|', expr.left, expr.right.right)
            if expr.left == Expr('~', expr.right.right, None):
                return Expr('|', expr.left, expr.right.left)
        return expr

    def process_expr(expr):
        if isinstance(expr, Expr):
            new_left = process_expr(expr.left)
            new_right = process_expr(expr.right)
            new_expr = Expr(expr.op, new_left, new_right)
            return apply_absorption(new_expr)
        return expr

    return [process_expr(arg) for arg in args]

