def find_path_type(path):
    if not os.path.exists(path):
        return "path does not exist"
    if os.path.isfile(path):
        return "file"
    if path.endswith('/0=ocfl_storage_root'):
        return "root"
    if path.endswith('/0=ocfl_object'):
        return "object"
    return "unknown path type"

def find_path_type(path):
    import os

    namaste_root = os.path.join(path, '0=ocfl_1.0')
    namaste_object = os.path.join(path, '0=ocfl_object_1.0')

    if os.path.isfile(namaste_root):
        return 'root'
    elif os.path.isfile(namaste_object):
        return 'object'
    elif os.path.isfile(path):
        return 'file'
    else:
        return 'Path does not exist or is not an OCFL compliant directory'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if os.path.isfile(path):
        return 'file'
    elif os.path.isdir(path):
        namaste_files = [f for f in os.listdir(path) if f.startswith('0=')]
        if '0=ocfl_1.0' in namaste_files:
            return 'root'
        elif any(f.startswith('0=ocfl_object_') for f in namaste_files):
            return 'object'
        else:
            return 'Unknown OCFL path type'
    else:
        return 'Path does not exist'

