    """Call the given command(s)."""
    for command in commands:
        full_command = [command] + args
        if verbose:
            print(f"Running: {' '.join(full_command)}")
        with subprocess.Popen(full_command, cwd=cwd, env=env, stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE, text=True) as process:
            stdout, stderr = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, full_command, output=stdout, stderr=stderr)
            if verbose and stdout:
                print(stdout)
            if verbose and stderr and not hide_stderr:
                print(stderr, file=sys.stderr)
        return stdout

