def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    for s, p, o in graph:
        if p == prop:
            roots.add(s)
            roots.discard(o)
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    children = set(graph.subjects(prop))
    nodes = set(graph.subjects()) | set(graph.objects())
    non_children = nodes - children
    roots.update(non_children)
    for child in children:
        if child not in graph.objects(predicate=prop):
            roots.add(child)
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    for subj, pred, obj in graph:
        if pred == prop:
            roots.add(subj)
            find_roots(graph, prop, roots)
    for subj, pred, obj in graph:
        if pred == prop and obj in roots:
            roots.remove(obj)
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    nodes_with_parents = set()
    for _, child, _ in graph.triples((None, prop, None)):
        nodes_with_parents.add(child)
    for node in graph.subjects():
        if node not in nodes_with_parents:
            roots.add(node)
    return roots

