def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    replaced_text = []

    def is_code_fence(line):
        return line.strip().startswith('```')

    lines = text.split('\n')
    for line in lines:
        if is_code_fence(line):
            code_block = not code_block
        if not code_block:
            found_tags = re.findall(r'#(\w+)', line)
            for tag in found_tags:
                tags.add(tag)
                if replacer:
                    line = re.sub(rf'#\b{tag}\b', replacer(tag), line)
        replaced_text.append(line)

    return tags, '\n'.join(replaced_text)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    code_block_start = re.compile(r'```')
    tag_pattern = re.compile(r'(?<!\w)(#\w+)(?!\w)')

    lines = text.split('\n')
    new_lines = []

    for line in lines:
        if code_block_start.search(line):
            code_block = not code_block
        if not code_block:
            for match in tag_pattern.finditer(line):
                tag = match.group(0)
                tags.add(tag)
                if replacer:
                    line = line[:match.start()] + replacer(tag) + line[match.end():]
        new_lines.append(line)

    return tags, '\n'.join(new_lines)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    modified_text = []
    i = 0
    while i < len(text):
        if text[i:i+3] == "```":
            code_block = not code_block
            modified_text.append(text[i:i+3])
            i += 3
        elif not code_block and text[i] == '#':
            tag_start = i
            i += 1
            while i < len(text) and text[i].isalnum():
                i += 1
            tag = text[tag_start:i]
            tags.add(tag)
            if replacer:
                modified_text.append(replacer(tag))
            else:
                modified_text.append(tag)
        else:
            modified_text.append(text[i])
            i += 1
    return tags, ''.join(modified_text)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    result = []

    def is_code_block(line):
        return line.strip().startswith('```')

    lines = text.split('\n')
    for line in lines:
        if is_code_block(line):
            code_block = not code_block
        if not code_block:
            tag_matches = re.findall(r'(?<!\S)(#(\w+))(?!\S)', line)
            for full_tag, tag in tag_matches:
                tags.add(tag)
                if replacer:
                    line = line.replace(full_tag, replacer(tag))
        result.append(line)

    return tags, '\n'.join(result)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    lines = text.split('\n')
    new_lines = []

    for line in lines:
        if line.strip().startswith('```'):
            code_block = not code_block
            new_lines.append(line)
            continue

        if not code_block:
            tag_matches = re.findall(r'#(\w+)', line)
            for tag in tag_matches:
                tags.add(tag)
                if replacer:
                    line = re.sub(rf'#\b{tag}\b', replacer(tag), line)

        new_lines.append(line)

    new_text = '\n'.join(new_lines)
    return tags, new_text

