def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    from xml.etree import ElementTree

    try:
        # Try parsing as JSON
        data = json.loads(document)
        if "links" in data:
            return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try parsing as XRD
        try:
            root = ElementTree.fromstring(document)
            if root.tag.endswith('XRD'):
                links = []
                for link in root.findall(".//link"):
                    link_data = {}
                    for attr, value in link.attrib.items():
                        link_data[attr] = value
                    links.append(link_data)
                return {"links": links}
        except ElementTree.ParseError:
            pass

    raise ValueError("Invalid Diaspora webfinger document")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Attempt to parse as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, attempt to parse as XRD
        root = ET.fromstring(document)
        xrd_data = {}
        for elem in root.iter():
            if elem.tag.endswith('}subject'):
                xrd_data['subject'] = elem.text
            elif elem.tag.endswith('}alias'):
                xrd_data['aliases'] = xrd_data.get('aliases', []) + [elem.text]
            elif elem.tag.endswith('}link'):
                link = {}
                for attr, value in elem.attrib.items():
                    link[attr] = value
                xrd_data['links'] = xrd_data.get('links', []) + [link]
        return xrd_data

