def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from xml.etree import ElementTree as ET

    base_url = "https://diaspora-federation.tokyo/.well-known/webfinger"
    params = {"resource": f"acct:{handle}"}

    response = requests.get(base_url, params=params)

    if response.status_code != 200:
        raise Exception(f"Failed to retrieve webfinger document: {response.status_code}")

    root = ET.fromstring(response.content)

    parsed_data = {
        "subject": root.attrib.get("subject"),
        "aliases": [alias.text for alias in root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias")],
        "links": [
            {
                "rel": link.attrib.get("rel"),
                "type": link.attrib.get("type"),
                "href": link.attrib.get("href")
            }
            for link in root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
        ]
    }

    return parsed_data

